changeSet.sql:
INSERT INTO case_handover_reason_policy ( code, label, client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, max_access_duration_minutes, updated_at, seeded_by_neutral_reasons) SELECT 'ADVICE_REQUESTED', 'Advice requested', client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, max_access_duration_minutes, CURRENT_TIMESTAMP, 1 FROM case_handover_reason_policy WHERE code = 'COUNSELLOR_ASKED_FOR_ADVICE' AND NOT EXISTS ( SELECT 1 FROM case_handover_reason_policy WHERE code = 'ADVICE_REQUESTED');
INSERT INTO case_handover_reason_policy ( code, label, client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, max_access_duration_minutes, updated_at, seeded_by_neutral_reasons) SELECT 'PLANNED_ABSENCE', 'Planned absence', client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, NULL, CURRENT_TIMESTAMP, 1 FROM case_handover_reason_policy WHERE code = 'COUNSELLOR_ON_HOLIDAY' AND NOT EXISTS ( SELECT 1 FROM case_handover_reason_policy WHERE code = 'PLANNED_ABSENCE');
-- Templates are not copied: the old ones may name the illness. INSERT INTO case_handover_reason_policy ( code, label, client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, max_access_duration_minutes, updated_at, seeded_by_neutral_reasons) SELECT 'UNPLANNED_ABSENCE', 'Unplanned absence', client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, NULL, NULL, CURRENT_TIMESTAMP, 1 FROM case_handover_reason_policy WHERE code = 'COUNSELLOR_IS_ILL' AND NOT EXISTS ( SELECT 1 FROM case_handover_reason_policy WHERE code = 'UNPLANNED_ABSENCE');
INSERT INTO case_handover_reason_policy ( code, label, client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, max_access_duration_minutes, updated_at, seeded_by_neutral_reasons) SELECT 'ASSIGNMENT_ENDED', 'Assignment ended', client_consent_required, client_consent_mode, access_allowed, enabled, display_order, policy_authority, client_notification_templates, NULL, CURRENT_TIMESTAMP, 1 FROM case_handover_reason_policy WHERE code = 'COUNSELLOR_LEFT' AND NOT EXISTS ( SELECT 1 FROM case_handover_reason_policy WHERE code = 'ASSIGNMENT_ENDED');
UPDATE case_handover_reason_policy SET enabled = 0, retired_by_neutral_reasons = 1 WHERE code IN ( 'COUNSELLOR_ASKED_FOR_ADVICE', 'COUNSELLOR_ON_HOLIDAY', 'COUNSELLOR_IS_ILL', 'COUNSELLOR_LEFT') AND enabled = 1;
